from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class PlanValidationEMSERVICEv1(SchemaObject):
    action_id = SchemaField(name="actionId", not_null=True)
    error_message = SchemaField(name="errorMessage")
    links = SchemaField(name="links")
    status = SchemaField(name="status", not_null=True)
    validation_id = SchemaField(name="validationId")

    def __init__(self, action_id, error_message, links, status, validation_id):
        self.action_id = action_id
        self.error_message = error_message
        self.links = links
        self.status = status
        self.validation_id = validation_id

        super(PlanValidationEMSERVICEv1, self).__init__()
